-- NextStep — Banco Completo — 3FN
CREATE DATABASE IF NOT EXISTS nextstep CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nextstep;
CREATE TABLE perfis(id_perfil INT NOT NULL AUTO_INCREMENT,nome VARCHAR(30) NOT NULL,CONSTRAINT pk_perfis PRIMARY KEY(id_perfil),CONSTRAINT uq_perfis UNIQUE(nome))ENGINE=InnoDB;
CREATE TABLE usuarios(id_usuario INT NOT NULL AUTO_INCREMENT,nome VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL,senha_hash VARCHAR(255) NOT NULL,idade TINYINT NOT NULL DEFAULT 18,cidade VARCHAR(100) DEFAULT NULL,estado CHAR(2) DEFAULT NULL,tem_passaporte TINYINT(1) NOT NULL DEFAULT 0,id_perfil INT NOT NULL DEFAULT 2,ativo TINYINT(1) NOT NULL DEFAULT 1,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT pk_usuarios PRIMARY KEY(id_usuario),CONSTRAINT uq_email UNIQUE(email),CONSTRAINT fk_usu_perfil FOREIGN KEY(id_perfil)REFERENCES perfis(id_perfil))ENGINE=InnoDB;
CREATE TABLE paises(id_pais INT NOT NULL AUTO_INCREMENT,nome VARCHAR(100) NOT NULL,bandeira VARCHAR(10) NOT NULL DEFAULT '',moeda VARCHAR(10) NOT NULL,idioma VARCHAR(80) NOT NULL,requer_visto TINYINT(1) NOT NULL DEFAULT 0,CONSTRAINT pk_paises PRIMARY KEY(id_pais))ENGINE=InnoDB;
CREATE TABLE cidades(id_cidade INT NOT NULL AUTO_INCREMENT,id_pais INT NOT NULL,nome VARCHAR(100) NOT NULL,custo_moradia DECIMAL(10,2) NOT NULL DEFAULT 0,custo_alimentacao DECIMAL(10,2) NOT NULL DEFAULT 0,custo_transporte DECIMAL(10,2) NOT NULL DEFAULT 0,custo_lazer DECIMAL(10,2) NOT NULL DEFAULT 0,custo_outros DECIMAL(10,2) NOT NULL DEFAULT 0,passagem_brl DECIMAL(10,2) NOT NULL DEFAULT 0,CONSTRAINT pk_cidades PRIMARY KEY(id_cidade),CONSTRAINT fk_cid_pais FOREIGN KEY(id_pais)REFERENCES paises(id_pais))ENGINE=InnoDB;
CREATE TABLE objetivos(id_objetivo INT NOT NULL AUTO_INCREMENT,descricao VARCHAR(60) NOT NULL,CONSTRAINT pk_objetivos PRIMARY KEY(id_objetivo))ENGINE=InnoDB;
CREATE TABLE projetos(id_projeto INT NOT NULL AUTO_INCREMENT,id_usuario INT NOT NULL,id_pais INT NOT NULL,id_cidade INT NOT NULL,id_objetivo INT NOT NULL,nome VARCHAR(150) NOT NULL,duracao_meses TINYINT NOT NULL,data_inicio DATE DEFAULT NULL,notas TEXT DEFAULT NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT pk_projetos PRIMARY KEY(id_projeto),CONSTRAINT fk_proj_usuario FOREIGN KEY(id_usuario)REFERENCES usuarios(id_usuario)ON DELETE CASCADE,CONSTRAINT fk_proj_pais FOREIGN KEY(id_pais)REFERENCES paises(id_pais),CONSTRAINT fk_proj_cidade FOREIGN KEY(id_cidade)REFERENCES cidades(id_cidade),CONSTRAINT fk_proj_objetivo FOREIGN KEY(id_objetivo)REFERENCES objetivos(id_objetivo))ENGINE=InnoDB;
CREATE TABLE plano_financeiro(id_plano INT NOT NULL AUTO_INCREMENT,id_projeto INT NOT NULL,custo_mensal DECIMAL(10,2) NOT NULL DEFAULT 0,valor_guardado DECIMAL(10,2) NOT NULL DEFAULT 0,meta_total DECIMAL(10,2) NOT NULL DEFAULT 0,passagem_brl DECIMAL(10,2) NOT NULL DEFAULT 0,CONSTRAINT pk_plano PRIMARY KEY(id_plano),CONSTRAINT uq_plano_proj UNIQUE(id_projeto),CONSTRAINT fk_plano_proj FOREIGN KEY(id_projeto)REFERENCES projetos(id_projeto)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE categorias_checklist(id_categoria INT NOT NULL AUTO_INCREMENT,nome VARCHAR(60) NOT NULL,CONSTRAINT pk_cat PRIMARY KEY(id_categoria))ENGINE=InnoDB;
CREATE TABLE checklist(id_item INT NOT NULL AUTO_INCREMENT,id_projeto INT NOT NULL,id_categoria INT NOT NULL,titulo VARCHAR(150) NOT NULL,descricao TEXT DEFAULT NULL,concluido TINYINT(1) NOT NULL DEFAULT 0,notas TEXT DEFAULT NULL,CONSTRAINT pk_checklist PRIMARY KEY(id_item),CONSTRAINT fk_chk_proj FOREIGN KEY(id_projeto)REFERENCES projetos(id_projeto)ON DELETE CASCADE,CONSTRAINT fk_chk_cat FOREIGN KEY(id_categoria)REFERENCES categorias_checklist(id_categoria))ENGINE=InnoDB;
CREATE TABLE timeline(id_evento INT NOT NULL AUTO_INCREMENT,id_projeto INT NOT NULL,id_categoria INT NOT NULL,titulo VARCHAR(150) NOT NULL,descricao TEXT DEFAULT NULL,data_prevista DATE NOT NULL,concluido TINYINT(1) NOT NULL DEFAULT 0,CONSTRAINT pk_timeline PRIMARY KEY(id_evento),CONSTRAINT fk_tl_proj FOREIGN KEY(id_projeto)REFERENCES projetos(id_projeto)ON DELETE CASCADE,CONSTRAINT fk_tl_cat FOREIGN KEY(id_categoria)REFERENCES categorias_checklist(id_categoria))ENGINE=InnoDB;
